"""Raw capacity and the weight partition of a binary neural population."""
from __future__ import annotations
from itertools import product
from math import comb
from typing import List, Tuple

Pattern = Tuple[int, ...]

def all_patterns(n: int) -> List[Pattern]:
    return [tuple(b) for b in product((0, 1), repeat=n)]

def weight(c: Pattern) -> int:
    return sum(c)

def verify_capacity_and_partition(n: int) -> None:
    patterns = all_patterns(n)
    assert len(patterns) == 2 ** n, "raw capacity must be 2^N"
    total = 0
    for k in range(n + 1):
        cnt = sum(1 for p in patterns if weight(p) == k)
        assert cnt == comb(n, k), "weight-k count must be C(N,k)"
        total += cnt
    assert total == 2 ** n, "sum of binomials must be 2^N"
    print(f"N={n}: 2^N={2**n}, weight counts {[comb(n,k) for k in range(n+1)]}")

if __name__ == "__main__":
    for n in range(0, 9):
        verify_capacity_and_partition(n)

"""Hamming-ball volume is center-independent and equals sum_{k<=r} C(N,k)."""
from __future__ import annotations
from itertools import product
from math import comb
from typing import List, Tuple

Pattern = Tuple[int, ...]

def all_patterns(n: int) -> List[Pattern]:
    return [tuple(b) for b in product((0, 1), repeat=n)]

def hamming(x: Pattern, y: Pattern) -> int:
    return sum(1 for a, b in zip(x, y) if a != b)

def ball_size(center: Pattern, r: int) -> int:
    n = len(center)
    return sum(1 for p in all_patterns(n) if hamming(center, p) <= r)

def volume_formula(n: int, r: int) -> int:
    return sum(comb(n, k) for k in range(r + 1))

def verify(n: int) -> None:
    pats = all_patterns(n)
    for r in range(n + 1):
        sizes = {ball_size(c, r) for c in pats}         # over ALL centers
        assert sizes == {volume_formula(n, r)}, (n, r, sizes)
    print(f"N={n}: every ball of radius r has volume {[volume_formula(n,r) for r in range(n+1)]}")

if __name__ == "__main__":
    for n in range(1, 8):
        verify(n)

"""Sphere-packing bound and the perfection of the Hamming(7,4) code."""
from __future__ import annotations
from itertools import combinations, product
from math import comb
from typing import List, Sequence, Tuple

Pattern = Tuple[int, ...]

def hamming(x: Pattern, y: Pattern) -> int:
    return sum(1 for a, b in zip(x, y) if a != b)

def min_distance(code: Sequence[Pattern]) -> int:
    ds = [hamming(a, b) for a, b in combinations(code, 2)]
    return min(ds) if ds else 10**9

def volume(n: int, r: int) -> int:
    return sum(comb(n, k) for k in range(r + 1))

def check_bound(code: Sequence[Pattern], name: str) -> None:
    n = len(code[0])
    t = (min_distance(code) - 1) // 2
    lhs, rhs = len(code) * volume(n, t), 2 ** n
    assert lhs <= rhs, f"sphere-packing bound violated by {name}"
    tag = "PERFECT (equality)" if lhs == rhs else "strict"
    print(f"{name}: N={n} |C|={len(code)} t={t}  {len(code)}*{volume(n,t)}={lhs} <= 2^{n}={rhs}  [{tag}]")

def hamming_7_4() -> List[Pattern]:
    code = []
    for d0, d1, d2, d3 in product((0, 1), repeat=4):
        code.append((d0, d1, d2, d3, d0 ^ d1 ^ d3, d0 ^ d2 ^ d3, d1 ^ d2 ^ d3))
    return code

if __name__ == "__main__":
    check_bound([(0, 0, 0), (1, 1, 1)], "repetition-3")
    check_bound(hamming_7_4(), "Hamming(7,4)")

