"""Enumerate a t-error-correcting neural codebook by greedy sphere covering."""
from __future__ import annotations
from itertools import product
from typing import List, Tuple

Pattern = Tuple[int, ...]

def hamming(x: Pattern, y: Pattern) -> int:
    return sum(1 for a, b in zip(x, y) if a != b)

def greedy_codebook(n: int, t: int) -> List[Pattern]:
    """Greedily pick codewords whose radius-t balls stay disjoint.

    Returns a t-error-correcting code (min distance >= 2t+1). By the
    Gilbert-Varshamov argument the result has size >= 2^N / V(N,2t).
    """
    d_min = 2 * t + 1
    code: List[Pattern] = []
    for cand in product((0, 1), repeat=n):
        if all(hamming(cand, c) >= d_min for c in code):
            code.append(cand)
    return code

if __name__ == "__main__":
    for n in (5, 7):
        c = greedy_codebook(n, 1)
        print(f"N={n}, t=1: greedy code size {len(c)}")

