"""Nearest-codeword decoder: correct up to t neuron misfires."""
from __future__ import annotations
from typing import List, Optional, Sequence, Tuple

Pattern = Tuple[int, ...]

def hamming(x: Pattern, y: Pattern) -> int:
    return sum(1 for a, b in zip(x, y) if a != b)

def decode(received: Pattern, codebook: Sequence[Pattern], t: int) -> Optional[Pattern]:
    """Return the unique codeword within distance t of `received`, else None.

    Correctness (guaranteed when the codebook has min distance >= 2t+1):
    if a codeword was corrupted by at most t flips, the true codeword is the
    unique one within distance t, by the triangle inequality.
    """
    best: Optional[Pattern] = None
    for c in codebook:
        if hamming(received, c) <= t:
            if best is not None:
                return None  # ambiguous -> code did not satisfy the distance bound
            best = c
    return best

if __name__ == "__main__":
    code = [(0, 0, 0), (1, 1, 1)]
    print(decode((1, 0, 0), code, 1))  # -> (0,0,0)
    print(decode((1, 1, 0), code, 1))  # -> (1,1,1)

