"""Compute sphere-packing capacity ceilings and code rate bounds."""
from __future__ import annotations
from math import comb, log2
from typing import Tuple

def volume(n: int, r: int) -> int:
    return sum(comb(n, k) for k in range(r + 1))

def capacity_ceiling(n: int, t: int) -> float:
    """Max codewords a t-error-correcting code on N neurons can have: 2^N / V(N,t)."""
    return 2 ** n / volume(n, t)

def rate_bound(n: int, t: int) -> float:
    """Upper bound on the code rate R = (1/N) log2 |C|."""
    return 1.0 - log2(volume(n, t)) / n

def table(n_values: Tuple[int, ...], t: int) -> None:
    for n in n_values:
        print(f"N={n:3d} t={t}: ceiling={capacity_ceiling(n,t):14.2f}  rate<={rate_bound(n,t):.4f}")

if __name__ == "__main__":
    table((7, 15, 31, 63), t=1)
    table((7, 15, 31, 63), t=2)
